-- Pesquisa interna de dropshipping. Benchmarks varejistas nao sao custos de fornecedor.
CREATE TABLE IF NOT EXISTS supplier_candidates (slug text PRIMARY KEY,product_name text NOT NULL,category text NOT NULL,reference_price_cents integer NOT NULL CHECK(reference_price_cents>=0),reference_merchant text NOT NULL,reference_note text NOT NULL,national_supplier text NOT NULL,international_supplier text NOT NULL,risk_level text NOT NULL CHECK(risk_level IN ('low','medium','high')),status text NOT NULL DEFAULT 'candidate' CHECK(status IN ('candidate','quoted','approved','rejected')),supplier_cost_cents integer CHECK(supplier_cost_cents>=0),shipping_cents integer CHECK(shipping_cents>=0),target_margin_pct numeric(5,2) NOT NULL DEFAULT 20,notes text NOT NULL DEFAULT '',supplier_authorized boolean NOT NULL DEFAULT false,invoice_confirmed boolean NOT NULL DEFAULT false,stock_confirmed boolean NOT NULL DEFAULT false,shipping_confirmed boolean NOT NULL DEFAULT false,returns_confirmed boolean NOT NULL DEFAULT false,tracking_confirmed boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_options (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,region text NOT NULL,website text NOT NULL,product_categories text NOT NULL,published_terms text NOT NULL,costs_confirmed boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'needs_verification',created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS supplier_authorized boolean NOT NULL DEFAULT false;
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS invoice_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS stock_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS shipping_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS returns_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE supplier_candidates ADD COLUMN IF NOT EXISTS tracking_confirmed boolean NOT NULL DEFAULT false;
